-- Mod-authored splash painting descriptions for era changes, it_IT overlay.
-- Baseline in CivVAccess_EraDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_MISSING"] = "Nessuna descrizione per quest'epoca."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_CLASSICAL"] =
    "Un grande tempio colonnato si erge in cima a una collina terrazzata; sale più basse con colonnati scendono a destra. Giardini risalgono il pendio sotto di essi, dove strette scalinate serpeggiano accanto a uno sperone di roccia pallida affollato di cipressi e arbusti in fiore. Tutto il marmo splende di un caldo oro dorato al sole."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MEDIEVAL"] =
    "Campi di grano dorati si distendono sotto una città murata di torri pallide su una collina. Stendardi rossi pendono dai suoi merli; il più grande porta un uccello nero con le ali spiegate. È il tempo del raccolto: contadini curvi raccolgono il grano tagliato, altri portano alti covoni sulle spalle, e operai al centro ammucchiano un carro trainato da un paio di buoi scuri. Gli alberi si piegano negli angoli in alto sotto un cielo soffuso e velato."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_RENAISSANCE"] =
    "In alto sui tetti di Firenze, Michelangelo sta su una scala di legno mentre scolpisce il colossale David di marmo bianco. La testa e le spalle della statua da sole riempiono la sinistra del quadro; lo scultore arriva appena oltre la sua spalla. Sotto, i tetti di tegole rosse si distendono fino alla grande cupola del Duomo di Firenze e a un sottile campanile. Dietro di essi, una luce dorata squarcia il cielo cupo da tempesta."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_INDUSTRIAL"] =
    "Un battello a ruote rosso e bianco attraversa il porto di New York in primo piano, lasciando una scia di fumo da due ciminiere nere. I passeggeri si affollano sui ponti doppi. Dietro di esso la Statua della Libertà si erge verde contro un cielo ambrato e nebbioso; altre navi avanzano a vapore sull'acqua oltre. Fumo e foschia tingono l'intera scena di un caldo seppia e oro."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MODERN"] =
    "L'osservatore guarda dal tetto di un grattacielo attraverso una città piena di altri grattacieli. Le torri illuminate si allontanano isolato dopo isolato nella foschia dorata. In basso, sopraelevate autostrade si snodano attraverso uno svincolo ampio dove auto e camion scorrono lungo le curve. L'intero dipinto è un solo colore, oro e seppia come una fotografia virata."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_POSTMODERN"] =
    "Un sole basso arde in fondo a una strada del centro anni Cinquanta, inondandola di luce dorata. Uomini in abito e fedora camminano sul marciapiede a destra con le spalle all'osservatore, oltre tende e una grande insegna luminosa con lettere. Berline tondeggianti scure sono parcheggiate lungo il bordo o passano oltre. Davanti, gli edifici si dissolvono nel bagliore."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_FUTURE"] =
    "Una città futuristica risplende lungo una costa dorata, le sue torri sottili che si allontanano lungo la riva nella foschia. A sinistra un aereo rosso e bianco affusolato vira sull'acqua; dietro di esso un ponte sospeso scavalca la baia. In primo piano a destra un complesso a cupola di cromo e vetro è costruito dentro le scogliere stesse. Il verde ricopre le sue terrazze; una figura solitaria sta su una passerella."
